mapper.select:
select 
from sys_homework h inner join sys_class c on c.id=h.class_id
left join sys_homework_submission s on s.homework_id=h.id and s.student_id=#{studentId}
where h.class_id=#{classId} and h.start_time <= #{now}
and s.id is null and h.deadline >= #{now}
and s.id is not null
and s.id is null and h.deadline < #{now}
order by h.homework_date desc,h.id desc

select 
from sys_homework h inner join sys_class c on c.id=h.class_id
left join sys_homework_submission s on s.homework_id=h.id and s.student_id=#{studentId}
where h.id=#{homeworkId} and h.class_id=#{classId} and h.start_time <= #{now}
